/**  Shared physical tile capabilities for UI filtering and command validation. */
export type TileCapabilities_Deserialize = {
	fluid?: string | null,
	destroys_dropped_items: boolean,
};

/**  Shared physical tile capabilities for UI filtering and command validation. */
export type TileCapabilities_Serialize = {
	fluid: string | null,
	destroys_dropped_items: boolean,
};

/**
 *  地格销毁组件：把物品扔到指定地格上销毁（原版的岩浆）。
 * 
 *  判据是地格的 `TileComponent.destroys_dropped_items`——不是所有地格都能销毁，
 *  所以地格必须显式指定。任何物品都可以扔进去。
 */
export type TileDisposeMechanic = TileDisposeMechanic_Serialize | TileDisposeMechanic_Deserialize;

/**  地格销毁：换地格（必须带 `destroys_dropped_items`）或换被销毁的物品。 */
export type TileDisposeMechanicAction = ({ "set-tile": {
	tile: string,
} }) & { "set-item"?: never } | ({ "set-item": {
	item: IdWithQuality,
} }) & { "set-tile"?: never };

/**
 *  地格销毁组件：把物品扔到指定地格上销毁（原版的岩浆）。
 * 
 *  判据是地格的 `TileComponent.destroys_dropped_items`——不是所有地格都能销毁，
 *  所以地格必须显式指定。任何物品都可以扔进去。
 */
export type TileDisposeMechanic_Deserialize = {
	/**  地格名（必须有 `destroys_dropped_items`）。 */
	tile?: string,
	/**  被销毁的物品。 */
	item?: IdWithQuality,
};

/**
 *  地格销毁组件：把物品扔到指定地格上销毁（原版的岩浆）。
 * 
 *  判据是地格的 `TileComponent.destroys_dropped_items`——不是所有地格都能销毁，
 *  所以地格必须显式指定。任何物品都可以扔进去。
 */
export type TileDisposeMechanic_Serialize = {
	/**  地格名（必须有 `destroys_dropped_items`）。 */
	tile: string,
	/**  被销毁的物品。 */
	item: IdWithQuality,
};

/**
 *  地格抽取组件：在指定地格上放抽取机械，产出**该地格对应的流体**。
 * 
 *  地格决定产出什么（`TileComponent.fluid`：water / lava / heavy-oil / …），
 *  机械决定产出多少（`OffshorePumpComponent.pumping_speed`）。原版里
 *  offshore-pump 的 `fluid_box` 没有 filter——抽什么由地格决定——所以这两件事
 *  必须分开配置。原版 offshore-pump 的 `energy_source` 是 `void`（不耗电）。
 */
export type TileExtractMechanic = TileExtractMechanic_Serialize | TileExtractMechanic_Deserialize;

/**  地格抽取：换地格（决定产出哪种流体）或换机械（决定速率）。 */
export type TileExtractMechanicAction = ({ "set-tile": {
	tile: string,
} }) & { "set-machine"?: never } | ({ "set-machine": {
	machine: IdWithQuality,
} }) & { "set-tile"?: never };

/**
 *  地格抽取组件：在指定地格上放抽取机械，产出**该地格对应的流体**。
 * 
 *  地格决定产出什么（`TileComponent.fluid`：water / lava / heavy-oil / …），
 *  机械决定产出多少（`OffshorePumpComponent.pumping_speed`）。原版里
 *  offshore-pump 的 `fluid_box` 没有 filter——抽什么由地格决定——所以这两件事
 *  必须分开配置。原版 offshore-pump 的 `energy_source` 是 `void`（不耗电）。
 */
export type TileExtractMechanic_Deserialize = {
	/**  地格名（决定产出的流体）。 */
	tile?: string,
	/**  抽取机械（决定速率）。 */
	machine?: IdWithQuality,
};

/**
 *  地格抽取组件：在指定地格上放抽取机械，产出**该地格对应的流体**。
 * 
 *  地格决定产出什么（`TileComponent.fluid`：water / lava / heavy-oil / …），
 *  机械决定产出多少（`OffshorePumpComponent.pumping_speed`）。原版里
 *  offshore-pump 的 `fluid_box` 没有 filter——抽什么由地格决定——所以这两件事
 *  必须分开配置。原版 offshore-pump 的 `energy_source` 是 `void`（不耗电）。
 */
export type TileExtractMechanic_Serialize = {
	/**  地格名（决定产出的流体）。 */
	tile: string,
	/**  抽取机械（决定速率）。 */
	machine: IdWithQuality,
};

export type TimeScale = "seconds" | "minutes" | "hours";

